        "molecularWeight": "3752.1 g/mol",
        "mechanismOfAction": "Liga-se com alta afinidade e ativa seletivamente o receptor de GLP-2 (GLP-2R), acoplado à proteína Gs, localizado em células enteroendócrinas, miofibroblastos subepiteliais e neurônios do plexo mioentérico. Desencadeia a liberação local de fatores de crescimento parácrinos, predominantemente o Fator de Crescimento Semelhante à Insulina 1 (IGF-1), fator de crescimento de queratinócitos (KGF) e óxido nítrico endotelial. Estimula a hiperplasia da mucosa do intestino delgado, aumentando a profundidade das criptas, o comprimento das vilosidades intestinais, o fluxo sanguíneo mesentérico e a expressão de transportadores de glicose (SGLT-1), promovendo expressivo aumento na capacidade absortiva de fluidos, eletrólitos e macronutrientes.",
        "summary": "Análogo recombinante de 33 aminoácidos do peptídeo semelhante ao glucagon 2 (GLP-2), modificado com glicina na posição 2 para conferir resistência à enzima DPP-4 e prolongar sua ação biológica. Aprovado mundialmente sob os nomes comerciais Gattex e Revestive para o tratamento de pacientes adultos e pediátricos (≥1 ano) com Síndrome do Intestino Curto (SBS) dependentes de suporte parenteral. Atua estimulando a proliferação epitelial, aumentando a altura das vilosidades intestinais e reduzindo significativamente a dependência de nutrição parenteral e hidratação endovenosa.",
        "pharmacologicalClass": "Regeneração & Tecidos",
